using System;
using Godot;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.Nodes.Rooms;
using Seductress.SeductressCode.Systems;

namespace Seductress.SeductressCode.UI;

/// <summary>
/// [Claude, 2026-11-18] Shows the right belly and breasts on the combat rig.
///
/// The rig (seductress_visuals.tscn, generated by tools/seductress_rig/battle) carries every
/// variant as a hidden node under <c>Visuals/Parts</c>; the idle animation already moves them
/// all, so this only toggles <c>Visible</c>.
///
/// <b>Belly</b> — [Gorim, 2026-11-18] one stage per band, cap 6:
/// <code>
/// pregnancy = min(stage, 3)
/// inflation = min(floor((Ass - 200) / 100), 3), not below 0
/// band      = min(pregnancy + inflation, 6)
/// </code>
/// Band k shows <c>BELLY_overlay/stage{k}</c> and the join patch
/// <c>PAIR_overlay/{breasts}__belly{k}</c>, where {breasts} is <c>base</c> or the variant name.
///
/// <b>Breasts</b> — [Gorim, art spec 1b] four states that scale with pregnancy stage. [Claude]
/// read as: Stage 0 is the normal wrap, Stages 1-3 are <c>wrap__stage1..3</c>. The rig also has
/// five <c>nude__*</c> sizes; nothing in the game picks those yet.
///
/// <b>Milk</b> — [Gorim, 2026-11-18] shown while lactating (<see cref="Pregnancy.IsLactating"/>,
/// which the mod sets from conception until one combat after birth).
/// <c>MILK_overlay/{breasts}</c> is the milk on the breasts; <c>MILK_overlay/{breasts}__drip</c>
/// is the run onto the stomach and only fits the flat belly, so it shows at band 0 only.
///
/// Driven from <see cref="ReservoirHud"/>'s per-frame refresh rather than from hooks on every
/// place the Womb or Ass can change: the HUD is created once per combat, which is also how often
/// the rig scene is re-instanced, and the check is two integer reads when nothing has changed.
/// </summary>
public sealed class RigVisuals
{
    public const int MaxBand = 6;
    private const string PartsPath = "Parts";
    private const string BaseBreasts = "base";

    private readonly Player _player;
    private Node? _parts;
    private int _band = -1;
    private string? _breasts;
    private bool _milk;
    private bool _warned;

    public RigVisuals(Player player) => _player = player;

    public static int Band(ReservoirState r)
    {
        var pregnancy = Math.Min(r.PregnancyStage, 3);
        var inflation = Math.Clamp((r.Ass - 200) / 100, 0, 3);
        return Math.Min(pregnancy + inflation, MaxBand);
    }

    /// <summary>"base" for the normal wrap, otherwise the rig's variant name.</summary>
    public static string Breasts(ReservoirState r) =>
        r.PregnancyStage <= 0 ? BaseBreasts : $"wrap__stage{Math.Min(r.PregnancyStage, 3)}";

    public void Refresh()
    {
        if (_parts is null || !GodotObject.IsInstanceValid(_parts))
        {
            _parts = FindParts();
            _band = -1;
            _breasts = null;
            _milk = false;
            if (_parts is null) return;
        }

        var r = Reservoirs.Of(_player.RunState);
        var band = Band(r);
        var breasts = Breasts(r);
        var milk = Pregnancy.IsLactating(r);
        if (band == _band && breasts == _breasts && milk == _milk) return;

        var isBase = breasts == BaseBreasts;
        ShowOnly("BELLY_overlay", band > 0 ? $"stage{band}" : null);
        ShowOnly("PAIR_overlay", band > 0 ? $"{breasts}__belly{band}" : null);
        ShowOnly("BREASTS_under", isBase ? null : breasts);
        ShowOnly("BREASTS_overlay", isBase ? "base_hem" : breasts);
        if (_parts.GetNodeOrNull<CanvasItem>("BREASTS_plus_wrap_variant") is { } wrap) wrap.Visible = isBase;

        ShowOnly("MILK_overlay", milk ? breasts : null, milk && band == 0 ? $"{breasts}__drip" : null);

        MainFile.Logger.Info($"[Seductress] Rig: belly {_band} -> {band}, breasts {_breasts ?? "?"} -> {breasts}, milk {milk}");
        _milk = milk;
        _band = band;
        _breasts = breasts;
    }

    /// <summary>Shows the named children of a group and hides their siblings; null names are skipped.</summary>
    private void ShowOnly(string group, string? child, string? second = null)
    {
        var node = _parts!.GetNodeOrNull(group);
        if (node is null) return; // an older pck without this group: leave the rig as it is

        foreach (var c in node.GetChildren())
        {
            if (c is not CanvasItem item) continue;
            var name = c.Name.ToString();
            item.Visible = name == child || name == second;
        }

        foreach (var wanted in new[] { child, second })
        {
            if (wanted is not null && node.GetNodeOrNull(wanted) is null)
                MainFile.Logger.Info($"[Seductress] Rig: no node {group}/{wanted}");
        }
    }

    private Node? FindParts()
    {
        var body = NCombatRoom.Instance?.GetCreatureNode(_player.Creature)?.Visuals?.Body;
        if (body is null) return null; // the creature node can appear a frame or two after the HUD

        var parts = body.GetNodeOrNull(PartsPath);
        if (parts is null && !_warned)
        {
            _warned = true;
            MainFile.Logger.Info($"[Seductress] Rig parts not found at {PartsPath}; belly and breasts stay as drawn");
        }
        return parts;
    }
}
